contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to) public payable {
        require(to != address(0));
        require(to != address(c));
        require(to != address(this));

        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeToBalance = to.balance;

        bool reverted;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted ? (address(c).balance == beforeContractBalance && to.balance == beforeToBalance) : (address(c).balance == 0 && to.balance == beforeToBalance + beforeContractBalance));
    }

    receive() external payable {}
}

